import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 59 Collecting","description":"学习 动名词作主语与宾语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 59 Collecting","description":"学习 动名词作主语与宾语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 动名词作主语与宾语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 58 A spot of bother","link":"/life/english/new-concept/book-3/unit-03/lesson-058"},"next":{"text":"第三册：培养技能 · Lesson 60 Too early and too late","link":"/life/english/new-concept/book-3/unit-03/lesson-060"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 58 A spot of bother","link":"/life/english/new-concept/book-3/unit-03/lesson-058"},"next":{"text":"第三册：培养技能 · Lesson 60 Too early and too late","link":"/life/english/new-concept/book-3/unit-03/lesson-060"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-059.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-059.md"}'),l={name:"life/english/new-concept/book-3/unit-03/lesson-059.md"};function i(s,e,r,c,h,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-59-collecting" tabindex="-1">第三册：培养技能 · Lesson 59 Collecting <a class="header-anchor" href="#第三册-培养技能-·-lesson-59-collecting" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 59 Collecting&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从收藏的动机、分类与成本练习说明长期活动的变化。收藏可以出于兴趣、研究或纪念，不能简单等同于积累昂贵物品。学习动名词作为主语、宾语和介词宾语，准确表达“收集这项活动”与“被收集的东西”，并注意活动名词的主谓一致。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>collection</td><td>/kəˈlekʃən/</td><td>n.</td><td>收藏品</td><td>a small collection</td></tr><tr><td>catalogue</td><td>/ˈkætəlɒɡ/</td><td>v.</td><td>编目</td><td>catalogue objects</td></tr><tr><td>curiosity</td><td>/ˌkjʊəriˈɒsəti/</td><td>n.</td><td>好奇心</td><td>satisfy curiosity</td></tr><tr><td>preserve</td><td>/prɪˈzɜːv/</td><td>v.</td><td>保存</td><td>preserve a document</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>take an interest in — 对某事产生兴趣</li><li>build up — 逐步积累</li></ul><h2 id="语法讲解-动名词作主语与宾语" tabindex="-1">语法讲解：动名词作主语与宾语 <a class="header-anchor" href="#语法讲解-动名词作主语与宾语" aria-label="Permalink to &quot;语法讲解：动名词作主语与宾语&quot;">​</a></h2><p>动名词以 ing 形式把动作作为一个活动来谈论，作主语时通常按单数处理，如 Collecting stamps takes time。两个不同活动由 and 连接时通常用复数，但如果构成一个整体习惯也可按整体理解，应避免脱离语境硬套。介词后通常用动名词，如 interested in collecting。动名词还可带自己的宾语和状语，因此 Collecting old maps carefully 是整个主语短语。不要把动名词和现在分词仅按形式区分，应看它在句中承担名词角色还是描述动作状态。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Collecting old maps has taught me to notice how place names change.</p></blockquote><p>收藏旧地图让我学会留意地名如何变化。</p><p>Collecting old maps 整体作单数主语，谓语为 has taught；how 从句为 notice 的宾语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Collecting maps have taught me 错把 maps 当作主语中心；真正主语是收藏活动，通常用 has。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 Sorting them by year helps 时在 helps 前识别整个主语组，回听是否错误地因为 tickets 或 them 而使用复数谓语。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I collect tickets from local performances. Sorting them by year helps me remember which venues have closed. I keep only one ticket from each event, so the collection stays manageable.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句介绍一种不强调价格的收藏爱好，说明分类与收获。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>活动主语说明收益，最后一句给出范围规则与管理边界。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句为何使用 has 而非 have？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 主语是 Collecting old maps 这一活动。</p><p><strong>解析：</strong> maps 只是动名词的宾语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：She is interested in ___ postcards.（collect/collecting）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> collecting</p><p><strong>解析：</strong> 介词 in 后接动名词。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>例句收藏带来的学习成果是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 留意地名的变化。</p><p><strong>解析：</strong> how place names change 给出具体内容。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：动名词作主语与宾语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-058">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-060">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=t(l,[["render",i]]);export{u as __pageData,g as default};
